const types = [TypeError, RangeError, SyntaxError, ReferenceError, EvalError, URIError, AggregateError];
for (const C of types) {
  const e = C === AggregateError ? new C([], "x") : new C("x");
  console.log(C.name.padEnd(15),
    "instanceof Error:", e instanceof Error,
    "| parent of prototype is Error.prototype:", Object.getPrototypeOf(C.prototype) === Error.prototype);
}
try { null.x; } catch (e) {
  console.log(e instanceof TypeError, e instanceof Error, e instanceof RangeError); // true true false
}

function attempt(thrower) {
  try { thrower(); } catch (e) {
    console.log(typeof e, "| has stack:", typeof e === "object" && "stack" in e, "| value:", String(e));
  }
}
attempt(() => { throw "just a string"; });
attempt(() => { throw { code: 42 }; });
attempt(() => { throw new Error("a real error"); });

