function handle(e) {
  if (!(e instanceof DOMException)) return "rethrow";
  const map = {
    AbortError: "ignore - user cancelled",
    QuotaExceededError: "free some storage",
    NotAllowedError: "ask the user to click first",
    InvalidStateError: "retry when ready",
  };
  return map[e.name] || "log and report";
}
for (const n of ["AbortError", "QuotaExceededError", "NotAllowedError", "InvalidStateError", "OperationError"]) {
  console.log(n, "=>", handle(new DOMException("", n)));
}
console.log(handle(new Error("plain")));

topics.description:
A `catch` block catches **everything** thrown inside `try` - programmer bugs, network failures, your own validation errors. Good error handling therefore *discriminates*: handle what you expect, rethrow the rest.

### Four ways to identify an error
| Technique | Example | Notes |
|---|---|---|
| `instanceof` | `e instanceof TypeError` | best for classes in the **same realm** |
| `name` | `e.name === "AbortError"` | needed for `DOMException`; works across iframes |
| custom `code` field | `e.code === "ENOENT"` | Node.js style, stable machine-readable id |
| `Error.isError(e)` | true for real errors | new (ES2026); works across realms and for DOMException |

### The golden pattern
```js
try {
  doWork();
} catch (e) {
  if (e instanceof ValidationError) {
    showMessage(e.message);        // expected
  } else if (e instanceof NetworkError) {
    scheduleRetry();               // expected
  } else {
    throw e;                       // unexpected: do NOT swallow
  }
}
```

### Cross-realm trap
An error created inside an `iframe` or `vm` context has *that realm's* `Error` constructor, so `e instanceof Error` is **false** in the parent page. Use `Error.isError(e)`, or compare `Object.prototype.toString.call(e) === "[object Error]"`, or check `e.name`.

### Also remember
- Anything can be thrown: `e` might be a string, `null` or a plain object. Normalise first: `const err = e instanceof Error ? e : new Error(String(e))`.
- In TypeScript the caught variable is `unknown` (with `useUnknownInCatchVariables`), forcing a type check.
- Match on **name/instanceof/code**, never on `message` text - it can change between versions and languages.

examples.code:
class ValidationError extends Error { constructor(m) { super(m); this.name = "ValidationError"; } }
class NetworkError extends Error { constructor(m) { super(m); this.name = "NetworkError"; } }

function run(task) {
  try { task(); return "ok"; }
  catch (e) {
    if (e instanceof ValidationError) return "show form message: " + e.message;
    if (e instanceof NetworkError) return "retry later";
    throw e;                                   // unknown -> let it bubble
  }
}
console.log(run(() => {}));
console.log(run(() => { throw new ValidationError("email is invalid"); }));
console.log(run(() => { throw new NetworkError("offline"); }));
try { run(() => { undefinedFunction(); }); }
catch (e) { console.log("bubbled up:", e.name, "-", e.message); }

function toError(e) {
  if (e instanceof Error) return e;
  if (typeof e === "string") return new Error(e);
  try { return new Error(JSON.stringify(e) ?? String(e)); } catch { return new Error(String(e)); }
}
for (const thrown of ["oops", { code: 7 }, null, undefined, 42, new RangeError("r")]) {
  try { throw thrown; }
  catch (e) { const err = toError(e); console.log(err.name + ": " + err.message); }
}

const fake = { name: "TypeError", message: "looks like one" };
console.log(fake instanceof TypeError, fake.name === "TypeError");   // false true (name can be spoofed)
const real = new TypeError("real");
console.log(real instanceof TypeError, Object.prototype.toString.call(real));
if (typeof Error.isError === "function") {
  console.log(Error.isError(real), Error.isError(fake), Error.isError(new DOMException("x", "AbortError")));
}
